import csv
import sys
from collections import OrderedDict


def count_nonempty(path):
    counts = OrderedDict()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            return counts
        for col in reader.fieldnames:
            counts[col] = 0
        for row in reader:
            for col in reader.fieldnames:
                value = (row.get(col) or "").strip()
                if value:
                    counts[col] += 1
    return counts


def main():
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件>", file=sys.stderr)
        sys.exit(1)
    counts = count_nonempty(sys.argv[1])
    if not counts:
        print("CSV 为空或缺少表头", file=sys.stderr)
        sys.exit(1)
    width = max(len(col) for col in counts)
    for col, n in counts.items():
        print(f"{col.ljust(width)}  {n}")


if __name__ == "__main__":
    main()
